DO $$
DECLARE v_page jsonb;
BEGIN
CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0950000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 95, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "95", "printedPageNumber": 95, "pdfPageNumber": 478, "sequenceIndex": 85, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0950100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "REQUISITES OF GOOD SALAAT SUGGESTED BY SOOFIA", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0950000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "There are some who shall remain in ruku and some in sajdah till eternity. Allah has combined all these postures of the Angels in our salaat, so that we may get our shares from each type of their worship. Recitation of the Qur''an in salaat is an addition over and above their worship. While salaat is the sum total of all the postures in the Angels'' methods of worship, it gives out its best when it is offered by a person possessing angelic habits. That is why the Prophet (Sallallaho alaihe wasallam) says, \"For (a good) salaat, keep your back and stomach light.\" The back of a person is said to be light when he has very few worldly encumbrances, and his stomach is light when he eats moderately to avoid indolence and laziness, which is a sure outcome of gluttony.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950200-0000-4000-8000-000000000001", "structuralNodeId": "b0950100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "REQUISITES OF GOOD SALAAT SUGGESTED BY SOOFIA", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}, {"id": "f0950300-0000-4000-8000-000000000001", "structuralNodeId": "b0950100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The Soofia write: \"There are twelve thousand virtues in salaat, which can be achieved through twelve points. If a person is to acquire full benefit from salaat, then, he must take care of these points. Sincerity is of course essential at every step. These points are as follows:\n\n1. Knowledge: An action performed without knowledge is far inferior to the one done with full knowledge about it. We should therefore know:\n(a) Which of the Islamic Practices are fardh and which are sunnat.\n(b) What is fardh and what is sunnat in wudhu and salaat.\n(c) How does Satan cause obstruction in the proper observance of salaat.\n\n2. Wudhu: We must try to:\n(a) Clean our heart of jealousy and malice, just as we wash the other parts of our body.\n(b) Keep ourselves clean of sins.\n(c) Be neither wasteful nor abstemious in the use of water.\n\n3. Dress: It should be:\n(a) Got through honest living.\n(b) Clean.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 95"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0960000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 96, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "96", "printedPageNumber": 96, "pdfPageNumber": 479, "sequenceIndex": 86, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0960000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 96"}, {"id": "f0960100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "(c) According to the Sunnat, e.g. the ankles should not be covered.\n(d) Simple, and should not display vanity and pride.\n\n4. Time: We should be:\n(a) Able to tell correct time at any moment.\n(b) Always watchful about Azaan.\n(c) Particular about the time of salaat, lest we should be too late for it.\n\n5. Qiblah: There are three things to be ensured in facing Qiblah:\n(a) We must face Qiblah physically.\n(b) Have the heart in union with Allah, for He is the Qiblah of the heart.\n(c) Be as attentive as a slave is before his master.\n\n6. Intention: For this we need to be particular about three things:\n(a) We must be definite as to what salaat we are offering.\n(b) Remain constantly conscious of our presence before Allah, Who sees us.\n(c) Have perfect faith that Allah know all that is in our hearts.\n\n7. Takbeer Tahreemah: The essentials of ''Takbeer Tahreemah'' are:\n(a) To pronounce the words correctly.\n(b) To raise both hands right up to the ears. This signifies that we have severed our connection with all, except Allah;\n(c) To feel the greatness of Allah in our heart when we say Allaho Akbar.\n\n8. Qiyaam: While in Qiyaam we should:\n(a) Keep our gaze at the place of sajdah.\n(b) Feel in our heart that we are standing before Allah.\n(c) Not think of anything else.\n\n9. Qiraat: The essentials of Qiraat are:\n(a) To recite the Qur''an with Tajweed.\n(b) To ponder on the meanings of what we recite.\n(c) To bind ourselves to what we recite.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 96"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0970000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 97, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "97", "printedPageNumber": 97, "pdfPageNumber": 480, "sequenceIndex": 87, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0970100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "SIGNIFICANCE OF WORDING OF SALAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0970000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 97"}, {"id": "f0970100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "10. Ruku: The essentials of Ruku are:\n(a) To keep the back quite straight i.e. the whole body above the legs should be in one straight line.\n(b) To hold the knees firmly with fingers spread apart.\n(c) To recite Tasbeeh with humility and devotion.\n\n11. Sajdah: The essentials of Sajdah are:\n(a) To place the hands flat and close to the ears;\n(b) To keep elbows raised above the ground.\n(c) To recite Tasbeeh with devotion.\n\n12. Qa''dah: The essentials of Qa''dah are:\n(a) To sit up on the left foot, keeping the right one erect.\n(b) To recite Tashahhud with devotion, keeping the meaning in mind, for it contains greetings for the Prophet (Sallallaho alaihe wasallam) and prayer for the Muslim brethren.\n(c) To consider the concluding Salaam a definite greeting to the Angels as well as the people on the right and on the left.\n\nAs has been said already, sincerity is the essence of all these points, which requires us:\n1. To offer salaat with the sole purpose of pleasing Allah.\n2. To understand that it is only through the grace and favour of Allah that we are able to offer salaat.\n3. To hope for the reward promised by Allah.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 97"}, {"id": "f0970200-0000-4000-8000-000000000001", "structuralNodeId": "b0970100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "SIGNIFICANCE OF WORDING OF SALAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 97"}, {"id": "f0970300-0000-4000-8000-000000000001", "structuralNodeId": "b0970100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Salaat is really a very blessed and auspicious observance. Every word uttered in it is imbued with Allah''s greatness and sanctity. Thanaa, the opening prayer of salaat, contains extremely virtuous and devotional meaning viz:\n\n(1) Subhaanakallaahumma: O, Allah! I praise Thy Sanctity. Thou art free from all blemishes. Thou art above anything that is not the best.\n\n(2) Wa bihamdika: I praise Thy Glory. All virtues and beauties are admittedly for Thee and befit Thee.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 97"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;